import { Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  // Create geometry and material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ map: null, toneMapped: true });

  // Mesh that will be returned
  const node = new Mesh(geometry, material);
  node.userData.handlers = {};

  // Load texture asynchronously and apply when ready
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply any cinematic primitives listed in config (none for this node)
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(node, prim.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // Cleanup function
  node.userData.cleanup = () => {
    // Dispose primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
    // Kill GSAP timelines if any were created (none in this node)
    gsap.globalTimeline.clear();

    // Dispose material & geometry
    material.dispose();
    geometry.dispose();
    // Dispose texture
    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }
  };

  return node;
}
